# security_client.py - Local helper utilities for Key Management and Encryption\n\nimport os\nimport boto3\nfrom botocore.exceptions import ClientError\n\n# ---------------------------------------------------------------------------\n# KMS client configuration and helper functions\n# ---------------------------------------------------------------------------\n\ndef get_kms_client() -> boto3.client:\n    \"\"\"Return a configured AWS KMS client.\n\n    Uses AWS SDK defaults (credential chain, region from env).\n    \"\"\"\n    # Optional: enforce a specific region via env var\n    region = os.getenv('AWS_REGION', None)\n    return boto3.client('kms', region_name=region)\n\n# ---------------------------------------------------------------------------\n# Helper wrappers (minimal examples)\n# ---------------------------------------------------------------------------\n\ndef generate_data_key(key_id: str, key_spec: str = 'AES_256') -> dict:\n    \"\"\"Generate a data key via KMS and return raw response.\n\n    Returns the dict as returned by boto3 generate_data_key.\n    \"\"\"\n    client = get_kms_client()\n    try:\n        return client.generate_data_key(KeyId=key_id, KeySpec=key_spec)\n    except ClientError as e:\n        raise RuntimeError(f\"KMS data-key error: {e}\") from e\n\n# Placeholder for other helpers (decrypt, sign, verify) – actual implementations are in other scored files\n